//! The golden photos' built-in lens corrections against RAWmakase's own record
//! of them. Ours.
//!
//! Argentum's readers of the camera's own lens correction are copied from
//! RAWmakase's (engine `rm_lens_builtin/`, one file per make). RAWmakase
//! records what its decoder reads from each raw.pixls.us file
//! (`tests/corpus/dataset/pixls-decode.json`, MIT), so on the golden photos
//! ours must read the same correction, part by part. The record is
//! `src-tauri/tests/look/rm_lens_baselines.tsv`, generated by
//! `node scripts/rawmakase-lens-baselines.mjs <release>`, which leaves out the
//! fields our `LensCorrection` does not carry and names them on its Source
//! line.
//!
//! The two are measured in different images: RAWmakase's in its decoded
//! image (radius 1 at its half diagonal, the centre in fractions of it), ours
//! in the developed image, the default crop inside it. So they are compared
//! in pixels: the optical centre, where each part moves a point at each
//! distance from it, and each gain, once both default crops are the same
//! size.
//!
//! RAWmakase keeps a correction in two records, what is applied from the file
//! whatever the lens profile and what stands in for a profile that has none;
//! ours is one `LensCorrection` whose `always` says which. So a part is
//! compared with the first record's, else the stand-in's, and `always` is not
//! compared. Nor is `source`, the name shown for it ("DNG" here, "DNG opcodes"
//! there): what is compared is what changes the picture.

use argentum_engine::rm_lens_builtin::{DevelopedFrame, LensCorrection, Radial, reach};

const TABLE: &str = include_str!("../../../tests/look/rm_lens_baselines.tsv");

/// Equal within a tenth of a pixel where a part samples, a thousandth of a
/// gain, and a twentieth of a pixel for the optical centre: the two sample
/// the same functions at knots that differ with the image, and interpolate
/// between them.
const PX: f32 = 0.1;
const GAIN: f32 = 1e-3;
const CENTRE_PX: f32 = 0.05;

/// Parts our readers read where RAWmakase's read none: the golden photo's
/// sha256, the part, and why, with what removes the entry. One that no longer
/// differs fails the check, so the list stays true.
const OURS_ONLY: [(&str, &str, &str); 1] = [(
    "fb4f294e12cab7b507fd0b7c07f24e5d13e7c0dd127b534ce12c48d644c9363d",
    "vignetting",
    "a DJI drone writes FixVignetteRadial into OpcodeList3, which our dng.rs reads and RAWmakase's \
     does not (it reads OpcodeList2's); removed when RAWmakase reads it, or a render against \
     Lightroom shows it should not apply",
)];

/// The image a record is measured in: the decoded image's width and height,
/// and the default crop's left, top, width and height in it, in pixels.
#[derive(Clone, Copy, Debug, PartialEq)]
struct Frame {
    decoded: [f32; 2],
    crop: [f32; 4],
}

/// RAWmakase's record of one file: the image it is measured in, the
/// correction applied from the file, and the stand-in for a profile.
struct Recorded {
    frame: Frame,
    lens: Option<LensCorrection>,
    stand_in: Option<LensCorrection>,
}

impl Recorded {
    /// Both records as one correction: each part from the first, else the
    /// stand-in. `None` when RAWmakase reads no correction at all.
    fn merged(self) -> Option<LensCorrection> {
        let Recorded { lens, stand_in, .. } = self;
        let mut merged = lens.or_else(|| stand_in.clone())?;
        if let Some(stand_in) = stand_in {
            merged.distortion = merged.distortion.or(stand_in.distortion);
            merged.vignetting = merged.vignetting.or(stand_in.vignetting);
            merged.chromatic = merged.chromatic.or(stand_in.chromatic);
        }
        Some(merged)
    }
}

fn rows() -> impl Iterator<Item = (&'static str, Recorded)> {
    TABLE
        .lines()
        .filter(|line| !line.starts_with('#') && !line.is_empty())
        .map(|line| {
            let fields: Vec<&str> = line.split('\t').collect();
            let [_id, sha, frame, lens, stand_in] = fields[..] else {
                panic!("rm_lens_baselines.tsv: not five columns: {line:.40}");
            };
            let numbers: Vec<f32> = frame
                .split(' ')
                .map(|v| v.parse().unwrap_or(f32::NAN))
                .collect();
            let [w, h, left, top, cw, ch] = numbers[..] else {
                panic!("rm_lens_baselines.tsv, {line:.40}: not six numbers: {frame}");
            };
            let read = |json: &str| {
                serde_json::from_str(json)
                    .unwrap_or_else(|e| panic!("rm_lens_baselines.tsv, {line:.40}: {e}"))
            };
            (
                sha,
                Recorded {
                    frame: Frame {
                        decoded: [w, h],
                        crop: [left, top, cw, ch],
                    },
                    lens: read(lens),
                    stand_in: read(stand_in),
                },
            )
        })
}

/// RAWmakase's reading of the file with this sha256, both records as one,
/// and the image it is measured in: `None` when the table has no row for
/// it, a `None` correction when it reads none.
fn recorded(sha256: &str) -> Option<(Frame, Option<LensCorrection>)> {
    rows()
        .find(|(sha, _)| *sha == sha256)
        .map(|(_, recorded)| (recorded.frame, recorded.merged()))
}

/// One correction as it acts on its default crop, in pixels.
struct InPixels<'a> {
    lens: &'a LensCorrection,
    /// The optical centre, in pixels from the default crop's top left.
    centre: [f32; 2],
    /// Radius 1, in pixels.
    half: f32,
}

/// Does our reading of a file match RAWmakase's record of it? `Ok` when the
/// table has no row for the file. `frame` is where our developed image lies.
pub fn check(
    sha256: &str,
    ours: Option<&LensCorrection>,
    frame: Option<DevelopedFrame>,
) -> Result<(), String> {
    let Some((theirs_frame, theirs)) = recorded(sha256) else {
        return Ok(());
    };
    let (t, o) = match (theirs.as_ref(), ours) {
        (None, None) => return Ok(()),
        (Some(t), None) => return Err(format!("RAWmakase reads {}, ours nothing", t.source)),
        (None, Some(o)) => return Err(format!("ours reads {}, RAWmakase nothing", o.source)),
        (Some(t), Some(o)) => (t, o),
    };
    let Some(frame) = frame else {
        return Err("our developed image's frame could not be read".into());
    };
    let [ow, oh] = [frame.crop[2] as f32, frame.crop[3] as f32];
    let [_, _, cw, ch] = theirs_frame.crop;
    if (ow - cw).abs() > 0.5 || (oh - ch).abs() > 0.5 {
        return Err(format!(
            "developed image {ow} x {oh} in {:?}, RAWmakase's default crop {cw} x {ch} in {:?}",
            frame.decoded, theirs_frame.decoded
        ));
    }
    let ours = InPixels {
        lens: o,
        centre: {
            let [x, y] = o.centre.unwrap_or(LensCorrection::IMAGE_CENTRE);
            [x * ow, y * oh]
        },
        half: ow.hypot(oh) * 0.5,
    };
    let [dw, dh] = theirs_frame.decoded;
    let [left, top, ..] = theirs_frame.crop;
    let theirs = InPixels {
        lens: t,
        centre: {
            let [x, y] = t.centre.unwrap_or(LensCorrection::IMAGE_CENTRE);
            [x * dw - left, y * dh - top]
        },
        half: dw.hypot(dh) * 0.5,
    };
    let differ = differences(&ours, &theirs, [ow, oh]);
    let excused: Vec<&str> = OURS_ONLY
        .iter()
        .filter(|(sha, ..)| *sha == sha256)
        .map(|(_, part, _)| *part)
        .collect();
    let ours_only = |d: &String| {
        excused
            .iter()
            .any(|part| *d == format!("{part}: ours has a table, RAWmakase none"))
    };
    let mut left_over: Vec<String> = differ.iter().filter(|d| !ours_only(d)).cloned().collect();
    for part in &excused {
        if !differ
            .iter()
            .any(|d| d.starts_with(&format!("{part}: ours has")))
        {
            left_over.push(format!(
                "{part}: OURS_ONLY excuses a difference there is no longer - delete its entry"
            ));
        }
    }
    if left_over.is_empty() {
        Ok(())
    } else {
        Err(left_over.join("; "))
    }
}

/// Every way the two differ by more than the tolerances, as one line each.
fn differences(ours: &InPixels, theirs: &InPixels, size: [f32; 2]) -> Vec<String> {
    let (o, t) = (ours.lens, theirs.lens);
    let mut differ = Vec::new();
    if t.default_on != o.default_on {
        differ.push(format!(
            "default_on {} against {}",
            o.default_on, t.default_on
        ));
    }
    let off = (ours.centre[0] - theirs.centre[0]).hypot(ours.centre[1] - theirs.centre[1]);
    if off > CENTRE_PX {
        differ.push(format!(
            "optical centre ({:.2}, {:.2}) against ({:.2}, {:.2}) px",
            ours.centre[0], ours.centre[1], theirs.centre[0], theirs.centre[1]
        ));
    }
    // Out to the default crop's corner farthest from our centre.
    let farthest = reach([ours.centre[0] / size[0], ours.centre[1] / size[1]], size) * ours.half;
    let red = |c: &LensCorrection| c.chromatic.as_ref().map(|c| c[0].clone());
    let blue = |c: &LensCorrection| c.chromatic.as_ref().map(|c| c[1].clone());
    for (part, o_part, t_part, moves) in [
        (
            "distortion",
            o.distortion.clone(),
            t.distortion.clone(),
            true,
        ),
        ("red", red(o), red(t), true),
        ("blue", blue(o), blue(t), true),
        (
            "vignetting",
            o.vignetting.clone(),
            t.vignetting.clone(),
            false,
        ),
    ] {
        match (o_part, t_part) {
            (None, None) => {}
            (Some(_), None) => differ.push(format!("{part}: ours has a table, RAWmakase none")),
            (None, Some(_)) => differ.push(format!("{part}: RAWmakase has a table, ours none")),
            (Some(a), Some(b)) => {
                let (worst, at) = (0..=256)
                    .map(|i| {
                        let px = farthest * i as f32 / 256.;
                        let d = a.eval(px / ours.half) - b.eval(px / theirs.half);
                        // A part that moves the picture, in pixels; a gain as it is.
                        (if moves { d.abs() * px } else { d.abs() }, px)
                    })
                    .fold((0f32, 0f32), |w, d| if d.0 > w.0 { d } else { w });
                let (limit, unit) = if moves { (PX, " px") } else { (GAIN, "") };
                if worst > limit {
                    differ.push(format!(
                        "{part}: {worst:.3}{unit} apart at {at:.0} px from the centre"
                    ));
                }
            }
        }
    }
    differ
}

#[cfg(test)]
mod tests {
    use super::*;

    /// RAWmakase's frame, as ours.
    fn developed(frame: Frame) -> DevelopedFrame {
        let [w, h] = frame.crop[2..].try_into().unwrap();
        DevelopedFrame {
            decoded: [frame.decoded[0] as usize, frame.decoded[1] as usize],
            crop: [
                frame.crop[0] as usize,
                frame.crop[1] as usize,
                w as usize,
                h as usize,
            ],
        }
    }

    /// RAWmakase's record moved into its own default crop, as ours is: the
    /// centre and radii in the crop.
    fn as_ours(frame: Frame, lens: &LensCorrection) -> LensCorrection {
        let [dw, dh] = frame.decoded;
        let [left, top, w, h] = frame.crop;
        let [x, y] = lens.centre.unwrap_or(LensCorrection::IMAGE_CENTRE);
        let k = dw.hypot(dh) / w.hypot(h);
        let moved = |r: &Radial| Radial {
            knots: r.knots.iter().map(|x| x * k).collect(),
            values: r.values.clone(),
        };
        LensCorrection {
            vignetting: lens.vignetting.as_ref().map(moved),
            distortion: lens.distortion.as_ref().map(moved),
            chromatic: lens
                .chromatic
                .as_ref()
                .map(|c| [moved(&c[0]), moved(&c[1])]),
            centre: Some([(x * dw - left) / w, (y * dh - top) / h]),
            ..lens.clone()
        }
    }

    /// Every row reads as a correction our code knows, and the table holds the
    /// golden photos it says it holds.
    #[test]
    fn the_record_reads_as_our_corrections() {
        let rows: Vec<_> = rows().collect();
        assert_eq!(rows.len(), 10);
        let read = rows
            .into_iter()
            .map(|(sha, recorded)| (sha, recorded.merged()))
            .collect::<Vec<_>>();
        assert_eq!(read.iter().filter(|(_, lens)| lens.is_some()).count(), 8);
        let samples = include_str!("../../../tests/look/samples.tsv");
        for (sha, _) in &read {
            assert!(samples.contains(sha), "{sha} is not a golden photo");
        }
    }

    /// The same correction measured in the other image matches; a part off by
    /// a little does not, and says which.
    #[test]
    fn a_reading_is_compared_part_by_part_in_pixels() {
        let (sha, frame, lens) = rows()
            .map(|(sha, r)| (sha, r.frame, r.merged()))
            .find(|(_, frame, lens)| {
                frame.decoded != [frame.crop[2], frame.crop[3]]
                    && lens.as_ref().is_some_and(|l| l.chromatic.is_some())
            })
            .unwrap();
        let ours = as_ours(frame, &lens.unwrap());
        let developed = Some(developed(frame));
        assert_eq!(check(sha, Some(&ours), developed), Ok(()));
        assert!(check(sha, None, developed).is_err());

        let mut off = ours.clone();
        off.chromatic.as_mut().unwrap()[1].values[20] += 0.001;
        let said = check(sha, Some(&off), developed).unwrap_err();
        assert!(said.contains("blue") && !said.contains("red"), "{said}");

        let mut moved = ours.clone();
        moved.centre = moved.centre.map(|[x, y]| [x + 0.001, y]);
        let said = check(sha, Some(&moved), developed).unwrap_err();
        assert!(said.contains("optical centre"), "{said}");

        // Our own `always`, and the name shown, are not compared.
        let mut ours = ours;
        ours.always = Some(argentum_engine::rm_lens_builtin::Parts::ALL);
        ours.source = "another name".into();
        assert_eq!(check(sha, Some(&ours), developed), Ok(()));
    }

    /// A part RAWmakase keeps in the stand-in record counts as recorded.
    #[test]
    fn the_stand_in_fills_the_parts_the_first_record_leaves() {
        let radial = Radial {
            knots: vec![0.0, 1.0],
            values: vec![1.0, 1.01],
        };
        let lens = LensCorrection {
            source: "X".into(),
            default_on: true,
            chromatic: Some([radial.clone(), radial.clone()]),
            ..Default::default()
        };
        let stand_in = LensCorrection {
            source: "X".into(),
            distortion: Some(radial.clone()),
            ..Default::default()
        };
        let merged = Recorded {
            frame: Frame {
                decoded: [10., 10.],
                crop: [0., 0., 10., 10.],
            },
            lens: Some(lens),
            stand_in: Some(stand_in),
        }
        .merged()
        .unwrap();
        assert!(merged.default_on);
        assert_eq!(merged.distortion, Some(radial));
        assert!(merged.chromatic.is_some() && merged.vignetting.is_none());
    }

    /// The DJI photo's vignetting is ours alone, and excused while it is.
    #[test]
    fn a_part_only_ours_reads_is_excused_while_it_differs() {
        let (sha, _, _) = OURS_ONLY[0];
        let (frame, theirs) = recorded(sha).unwrap();
        let theirs = theirs.unwrap();
        let developed = Some(developed(frame));
        let mut ours = as_ours(frame, &theirs);
        assert!(
            check(sha, Some(&ours), developed)
                .unwrap_err()
                .contains("OURS_ONLY")
        );
        ours.vignetting = Some(Radial {
            knots: vec![0., 1.],
            values: vec![1., 1.5],
        });
        assert_eq!(check(sha, Some(&ours), developed), Ok(()));
    }

    #[test]
    fn a_file_the_record_does_not_hold_is_not_judged() {
        assert_eq!(check("not-a-golden-photo", None, None), Ok(()));
    }
}
